#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MiniCut update patch: EFFECT LAYERS
===================================
Adds a "+ Effect" layer system (Tint, Curves, Adjust, Blur, Motion / Radial / Area blur, Color split, Pixelate, Glitch,
Sharpen, Vignette, Glow, Grain, Chroma key ...) and replaces the old Color / Effects tabs.

Run it from the MiniCut folder (the one that contains file.py and the minicut/ folder):

    python apply_effects_patch.py            install the update
    python apply_effects_patch.py --check    only show what would change
    python apply_effects_patch.py --revert   undo the last install (restores the backed-up files)
    python apply_effects_patch.py --force    install even if you edited some of the files yourself

Only the files listed below are replaced.  Every replaced file is first copied to _patch_backup/<time>/.
"""
import base64, datetime, hashlib, json, os, py_compile, shutil, subprocess, sys, zlib

FILES = {'README_TH.md': {'b64': '',
                  'base': '2f08e89ca24addde86bff23814be344eaf17e08fae02c486a866236f1c4a2a88',
                  'new': 'e9df36a4303b3d2c01b5e4937db5eeac020275f12f3f3cdac43d6baf857fdae2',
                  'soft': True},
 'minicut/render/effects.py': {'b64': '',
                               'base': None,
                               'new': '078695788b29d9ef97418c680ff459f7d91c2e8bb1ba05aa8d855763fad0f414',
                               'soft': False},
 'minicut/render/nodegraph.py': {'b64': '',
                                 'base': '22b1eaddda191e41e55d74c31f82c12b8449ceb121871fd093d50d99243ce4a5',
                                 'new': '3b43b3fb011273bd23c5b686b617c88d838b8e6c562cbcefd6024d3472b44f43',
                                 'soft': False},
 'minicut/render/renderer.py': {'b64': '',
                                'base': '426e7d80406cc43c8f78b821f8ca2aa62d17db3d36eb5bf964635ced0c9d84e1',
                                'new': '3e10a8880d1425121a506c127e97c31aa3a1bba180159bbbd807309671fae072',
                                'soft': False},
 'minicut/shared/core.py': {'b64': '',
                            'base': '8e138b4d868ef01a6d7736411e8908707f030d4fc9b1289261398ff0805f6ab5',
                            'new': 'db598f6cf01e8680e9af3c7768c88f092d1c3911f4c433435449724a48437e61',
                            'soft': False},
 'minicut/workspace/effects_panel.py': {'b64': '',
                                        'base': None,
                                        'new': '74b35e006a459321e35269e7e5bc61acc31ff75e55efc65da53d2dae3953756a',
                                        'soft': False},
 'minicut/workspace/node_editor.py': {'b64': '',
                                      'base': 'a7f14bc54736d9bb30c055e972bbfa68e940f561ff9fdf84400d65a1e2c315af',
                                      'new': 'abad81b1e85023f6c71528ac73c30a2c4845170332cac30c7bd384cc6407831a',
                                      'soft': False},
 'minicut/workspace/panels.py': {'b64': '',
                                 'base': '4a69647532070f282553bec8d3682cece465d7369239ccd237394d45b37e38d0',
                                 'new': '189de3ae2ed13dd1774781cc92fef8b38a2069c1a79f720c2414f12f0e6248f2',
                                 'soft': False}}
HERE = os.path.dirname(os.path.abspath(__file__))
BACKUP_ROOT = os.path.join(HERE, "_patch_backup")
try: sys.stdout.reconfigure(errors="replace")
except Exception: pass


def norm_hash(b): return hashlib.sha256(b.replace(b"\r\n", b"\n")).hexdigest()
def path_of(rel): return os.path.join(HERE, *rel.split("/"))
def read(rel):
    p = path_of(rel)
    return open(p, "rb").read() if os.path.exists(p) else None
def payload(rel): return zlib.decompress(base64.b64decode(FILES[rel]["b64"]))
def say(msg=""): print(msg, flush=True)


def import_ok():
    """Can the program's modules be imported?  (a quick sanity check, no window is shown)"""
    code = "import os; os.environ['QT_QPA_PLATFORM']='offscreen'; import minicut.app"
    try:
        r = subprocess.run([sys.executable, "-c", code], cwd=HERE, capture_output=True, text=True, timeout=180)
        return r.returncode == 0, (r.stderr or r.stdout)[-1500:]
    except Exception as ex: return False, str(ex)


def status():
    rows = []
    for rel, info in FILES.items():
        cur = read(rel)
        if cur is None: rows.append((rel, "new", "will be created"))
        elif norm_hash(cur) == info["new"]: rows.append((rel, "same", "already up to date"))
        elif info["base"] is None or norm_hash(cur) == info["base"] or info["soft"]: rows.append((rel, "ok", "will be replaced"))
        else: rows.append((rel, "edited", "differs from the version this patch was made for"))
    return rows


def pause():
    if os.name == "nt" and "--no-pause" not in sys.argv: os.system("pause")


def latest_backup():
    if not os.path.isdir(BACKUP_ROOT): return None
    ds = sorted(d for d in os.listdir(BACKUP_ROOT) if os.path.exists(os.path.join(BACKUP_ROOT, d, "MANIFEST.json")))
    return os.path.join(BACKUP_ROOT, ds[-1]) if ds else None


def revert(bdir):
    man = json.load(open(os.path.join(bdir, "MANIFEST.json"), encoding="utf-8"))
    for rel in man["replaced"]: shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
    for rel in man["created"]:
        if os.path.exists(path_of(rel)): os.remove(path_of(rel))
    say("Restored %d file(s), removed %d new file(s) from %s" % (len(man["replaced"]), len(man["created"]), bdir))


def main():
    if not os.path.isfile(path_of("minicut/app.py")):
        say("ERROR: minicut/app.py not found next to this script.\nPut apply_effects_patch.py in the MiniCut folder (next to file.py) and run it again."); return 2
    if "--revert" in sys.argv:
        b = latest_backup()
        if not b: say("No backup found in _patch_backup/."); return 1
        revert(b); return 0
    rows = status(); say("MiniCut update: effect layers\n")
    for rel, st, note in rows: say("  %-42s %s" % (rel, note))
    say()
    if "--check" in sys.argv: return 0
    if all(st == "same" for _, st, _ in rows): say("Nothing to do: the update is already installed."); return 0
    bad = [rel for rel, st, _ in rows if st == "edited"]
    if bad and "--force" not in sys.argv:
        say("STOPPED: these files were changed after the version this patch was made for:\n  " + "\n  ".join(bad) +
            "\nInstalling would overwrite your edits (they would be backed up first).\nRun again with --force if that is what you want."); return 3
    base_ok, _ = import_ok()
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S"); bdir = os.path.join(BACKUP_ROOT, stamp); replaced, created = [], []
    os.makedirs(bdir, exist_ok=True)
    for rel, st, _ in rows:
        if st == "same": continue
        cur = path_of(rel)
        if os.path.exists(cur):
            dst = os.path.join(bdir, *rel.split("/")); os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy2(cur, dst); replaced.append(rel)
        else: created.append(rel)
    json.dump({"patch": "effects", "created": created, "replaced": replaced}, open(os.path.join(bdir, "MANIFEST.json"), "w", encoding="utf-8"), indent=1)
    try:
        for rel, st, _ in rows:
            if st == "same": continue
            p = path_of(rel); os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "wb") as f: f.write(payload(rel))
            if rel.endswith(".py"): py_compile.compile(p, doraise=True)
    except Exception as ex:
        say("ERROR while writing files: %s\nRestoring the backup ..." % ex); revert(bdir); return 1
    ok, err = import_ok()
    if base_ok and not ok:
        say("The program no longer imports after the update, restoring the backup.\n" + err); revert(bdir); return 1
    for sub in ("minicut/render", "minicut/workspace", "minicut/shared"):
        shutil.rmtree(os.path.join(path_of(sub), "__pycache__"), ignore_errors=True)
    say("Done. %d file(s) replaced, %d created.  Backup: %s" % (len(replaced), len(created), bdir))
    say("Start MiniCut as usual (Run_MiniCut.bat).  In the Properties panel use the Effects tab -> '+ Effect'.")
    say("To undo:  python apply_effects_patch.py --revert")
    return 0


if __name__ == "__main__":
    code = 1
    try: code = main()
    except Exception as ex: say("Unexpected error: %r" % (ex,))
    pause(); sys.exit(code)
